const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf');
  const font = await doc.embedFont(fontBytes);

  const pageW = 595, pageH = 842;
  const mx = 50, my = 50;
  const contentW = pageW - mx * 2;

  const sections = [
    { title: '文件与文档处理', items: [
      '读取、创建、编辑各类文件（代码、文本、配置等）',
      '生成 Office 文档：PDF、Word (.docx)、Excel (.xlsx)、PowerPoint (.pptx)',
      '在沙箱中执行 Shell 命令，运行脚本与程序',
      '搜索文件内容（grep）、按模式查找文件（glob）',
    ]},
    { title: '编程与开发', items: [
      '编写、调试、重构多种语言的代码（Python、JS/TS、Shell 等）',
      '安装依赖、运行测试、构建项目',
      '分析日志、排查错误、优化性能',
      'Git 操作与版本管理辅助',
    ]},
    { title: '数据分析与可视化', items: [
      '处理 CSV / JSON / Excel 数据，进行统计与聚合',
      '用 Python 生成图表与可视化报告',
      '数据清洗、转换、格式化处理',
    ]},
    { title: '研究与信息整理', items: [
      '阅读并总结长文档、论文、技术手册',
      '结构化整理信息，生成摘要与对比表',
      '多源信息交叉验证与综合分析',
    ]},
    { title: '任务规划与项目管理', items: [
      '将复杂需求拆解为可执行的步骤清单',
      '实时跟踪进度，动态调整计划',
      '在歧义或信息不足时主动确认假设',
    ]},
    { title: '交付与发布', items: [
      '将生成的文件发布为可下载附件',
      '渲染预览确保输出质量',
      '支持多种媒体类型：PDF、图片、Office 文档、CSV、JSON 等',
    ]},
  ];

  // --- Page 1: Title + first sections ---
  let page = doc.addPage([pageW, pageH]);
  let y = pageH - my;

  // Title
  y -= 30;
  page.drawText('AI 助手能力概览', { x: mx, y, size: 28, font });
  y -= 20;
  page.drawLine({ start: { x: mx, y }, end: { x: pageW - mx, y }, thickness: 1.5, color: { r: 0.2, g: 0.4, b: 0.7 } });
  y -= 25;
  page.drawText('以下是我可以为您完成的主要工作类型：', { x: mx, y, size: 12, font });
  y -= 30;

  const titleSize = 15;
  const itemSize = 11;
  const lineH = 18;
  const sectionGap = 14;

  function drawSection(sec, startY) {
    let cy = startY;
    // Check if title fits
    if (cy < my + 40) return null;
    page.drawText('■ ' + sec.title, { x: mx, y: cy, size: titleSize, font, color: { r: 0.15, g: 0.35, b: 0.65 } });
    cy -= lineH + 4;
    for (const item of sec.items) {
      if (cy < my + 20) return null;
      page.drawText('• ' + item, { x: mx + 12, y: cy, size: itemSize, font });
      cy -= lineH;
    }
    cy -= sectionGap;
    return cy;
  }

  let idx = 0;
  while (idx < sections.length) {
    const nextY = drawSection(sections[idx], y);
    if (nextY === null) {
      // Need new page
      page = doc.addPage([pageW, pageH]);
      y = pageH - my - 20;
      continue;
    }
    y = nextY;
    idx++;
  }

  // Footer note
  if (y > my + 30) {
    y -= 20;
    page.drawLine({ start: { x: mx, y }, end: { x: pageW - mx, y }, thickness: 0.5, color: { r: 0.6, g: 0.6, b: 0.6 } });
    y -= 18;
    page.drawText('如需了解更多或有特定需求，请直接告诉我！', { x: mx, y, size: 10, font, color: { r: 0.4, g: 0.4, b: 0.4 } });
  }

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/ai-capabilities.pdf', bytes);
  console.log('PDF generated successfully.');
})().catch(e => { console.error(e.stack); process.exit(1); });

